import os, sqlite3
from bs4 import BeautifulSoup
p=os.environ['IGNTU_CATALOG']
soup=BeautifulSoup(open(p, encoding='utf-8', errors='replace'), 'html.parser')
db=sqlite3.connect('file:assets/data/career_path.db?mode=ro', uri=True)
rows=db.execute('''WITH RECURSIVE tree(id,slug,parent_id,name,breadcrumb) AS (SELECT id,slug,parent_id,name,name FROM career_nodes WHERE parent_id IS NULL UNION ALL SELECT c.id,c.slug,c.parent_id,c.name,tree.breadcrumb||' > '||c.name FROM career_nodes c JOIN tree ON c.parent_id=tree.id) SELECT id,slug,breadcrumb FROM tree''').fetchall()
nodes={slug:(i,slug,crumb) for i,slug,crumb in rows}

def A(slug, relation, confidence): return slug, relation, confidence

def assign(name, dept):
    n=name.lower(); d=(dept or '').lower()
    if 'ancient indian history' in d: return A('ba_history','nearest-parent', 'medium')
    if 'biotechnology' in d: return A('msc_biotech','direct-discipline','high') if n.startswith('m.sc.') else A('bsc_bio','closest-specialization','medium')
    if 'botany' in d: return A('bsc_bio','closest-specialization','medium')
    if 'business management' in d: return A('bba','direct-discipline','high') if n.startswith('under graduate') else A('bba','nearest-parent','medium')
    if 'chemistry' in d: return A('msc_chemistry','direct-discipline','high') if n.startswith('m.sc.') else A('bsc_chemistry','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'department of commerce' in d: return A('mcom','direct-discipline','high') if n == 'm.com' else A('bcom','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'computer science' in d: return A('mca','direct-discipline','high') if n.startswith('master of computer application') else A('bsc_cs','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'economics' in d: return A('ba_economics','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'department of education' in d: return A('ba_education','direct-discipline','medium')
    if 'english and foreign' in d: return A('ba_english','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'environmental science' in d: return A('bsc_env','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'geography' in d: return A('art_social','nearest-parent','low')
    if 'geology' in d: return A('bsc_geology','direct-discipline','high' if n.startswith('m.sc.') else 'medium')
    if 'department of hindi' in d: return A('ba_hindi','direct-discipline' if not n.startswith('certificate') else 'closest-specialization','high' if n.startswith('under graduate') else 'medium' if not n.startswith('certificate') else 'low')
    if 'department of history' in d: return A('ba_history','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'home science' in d: return A('science_common','nearest-parent','low')
    if 'journalism' in d: return A('bjmc','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'linguistics' in d: return A('ba_foreign_lang','closest-specialization','low')
    if 'mathematics' in d: return A('msc_maths','direct-discipline','high') if n.startswith('m.sc.') else A('bsc_maths','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'museology' in d: return A('museum_curator','closest-specialization','medium')
    if 'nursing' in d: return A('bsc_nursing','nearest-parent','medium')
    if 'performing arts' in d: return A('music_course','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'pharmacy' in d: return A('bpharm','direct-discipline','high' if n.startswith('b. pharm') else 'medium')
    if 'philosophy' in d: return A('art_social','nearest-parent','low')
    if 'physical education' in d: return A('sports_career','direct-discipline','high' if n.startswith('bachelor') else 'medium')
    if 'physics' in d: return A('msc_physics','direct-discipline','high') if n.startswith('m.sc.') else A('bsc_physics','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'political science' in d: return A('ba_polsci','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'psychology' in d: return A('ba_psychology','direct-discipline','high' if n.startswith('under graduate') else 'medium')
    if 'sanskrit' in d: return A('ba_hindi','closest-specialization','low')
