    if 'tribal studies' in d: return A('ba_sociology','closest-specialization','low')
    if 'vocational education' in d:
        if 'agricultural' in n: return A('bsc_agriculture','closest-specialization','medium')
        if 'software' in n: return A('bca','closest-specialization','medium')
        if 'theatre' in n or 'film production' in n or 'media technology' in n: return A('bsc_film','closest-specialization','medium')
        if 'tourism' in n or 'hospitality' in n: return A('hotel_mgmt','closest-specialization','medium')
    if 'department of yoga' in d: return A('sports_career','closest-specialization','low')
    if 'zoology' in d: return A('bsc_bio','closest-specialization','medium')
    return None

def norm_level(data_level):
    return {'ug':'undergraduate','pg':'postgraduate','phd':'doctoral','diploma':'diploma','certificate':'certificate'}[data_level]

def credential(data_level):
    return {'ug':'Undergraduate (UG)','pg':'Postgraduate (PG)','phd':'Doctoral (PhD)','diploma':'Diploma','certificate':'Certificate'}[data_level]

def course_obj(i, card):
    name=card.select_one('h3').get_text(' ',strip=True)
    data_level=card.get('data-level')
    dur=card.select_one('.duration').get_text(' ',strip=True)
    mapping=assignment(name,card.get('data-dept'))
    assert mapping, name
    slug,relation,confidence=mapping
    node=nodes[slug]
    status='reviewed_against_local_tree' if confidence=='high' and relation=='direct-discipline' else 'reviewed_with_career_tree_label_issue'
    specialization=None
    if name == 'M.Pharm (Pharmaceutical Chemistry)': specialization='Pharmaceutical Chemistry'
    elif name == 'M.Pharm (Pharmaceutics)': specialization='Pharmaceutics'
    elif name == 'MBA (Tourism & Travel Management)': specialization='Tourism & Travel Management'
    return {
      'course_id':f'igntu-{i:03d}',
      'name':name,
      'level':norm_level(data_level),
      'credential':credential(data_level),
      'specialization':specialization,
      'duration':dur,
      'mode':'on-campus',
      'eligibility':None,
      'official_course_url':CATALOG_URL,
      'verification_status':'verified',
      'career_path_mappings':[{
        **node,
        'relation':relation,
        'confidence':confidence,
        'mapping_status':status,
      }],
      'mapping_gap':None,
    }

